// src/components/Login.js

import React, { useState } from 'react';
import axios from 'axios';

const Login = () => {
    // Form එකේ user type කරන email, password වගේ data මතක තියාගන්න තමයි `useState` use කරන්නේ.
    const [formData, setFormData] = useState({
        email: '',
        password: ''
    });

    const [error, setError] = useState(''); // Display errors to the user

    const { email, password } = formData;

    // Input fields වල user type කරන හැම වචනයක්ම state එකට update කරන function එක.
    const onChange = e => setFormData({ ...formData, [e.target.name]: e.target.value });

    // Form එක Submit කරාම (Login button එක click කරාම) වැඩ කරන function එක.
    const onSubmit = async e => {
        e.preventDefault(); // Form submit වෙද්දී page එක refresh වෙන එක නවත්තනවා.
        
        try {
            const config = {
                headers: {
                    'Content-Type': 'application/json'
                }
            };
            const body = JSON.stringify({ email, password });

            // Axios වලින් backend එකේ login endpoint එකට POST request එකක් යවනවා.
            // Proxy setup කරලා තියෙන නිසා full URL එක ('http://localhost:5000/api/users/login') ඕන නෑ.
            const res = await axios.post('/api/user/login', body, config);

            // --- Login Successful ---
            console.log('Login successful! Token:', res.data.token);
            
            // IMPORTANT: ලැබෙන token එක localStorage එකේ save කරගන්නවා.
            // අපි මේ token එක save කරන්නේ, user අනිත් pages වලට යද්දී 'login වෙලා ඉන්නේ' කියලා මතක තියාගන්න.
            localStorage.setItem('token', res.data.token);

            alert('Login Successful!');
            setError(''); // Clear any previous errors

            // You can redirect the user to the dashboard here
            // window.location.href = '/dashboard';

        } catch (err) {
            // --- Login Failed ---
            // Backend එකෙන් එවන error message එක අරගෙන user ට පෙන්නනවා.
            const errorMessage = err.response ? err.response.data.message : 'Login failed. Please try again.';
            console.error(errorMessage);
            setError(errorMessage); // Set the error message in state
        }
    };

    return (
        <div>
            <h2>Login</h2>
            <form onSubmit={onSubmit}>
                <div>
                    <input
                        type="email"
                        placeholder="Email Address"
                        name="email"
                        value={email}
                        onChange={onChange}
                        required
                    />
                </div>
                <div>
                    <input
                        type="password"
                        placeholder="Password"
                        name="password"
                        value={password}
                        onChange={onChange}
                        required
                    />
                </div>
                {/* Show error message if it exists */}
                {error && <p style={{ color: 'red' }}>{error}</p>}
                <input type="submit" value="Login" />
            </form>
        </div>
    );
};

export default Login;
